function IsNumeric(e) {
    var evt = (e) ? e : window.event; var charCode = (evt.keyCode) ? evt.keyCode : evt.which; if (charCode > 31 && (charCode < 48 || charCode > 57)) { return !1 }
    return !0
}; function isDecimal(evt) {
    var charCode = (evt.which) ? evt.which : event.keyCode
    if ((charCode != 46 || evt.currentTarget.value.indexOf('.') != -1) && (charCode < 48 || charCode > 57))
        return !1; return !0
}
function AppendHours(hdntimeSpanId, hourTextId) {
    if ($.isNumeric($("#" + hourTextId).val()) && parseInt($("#" + hourTextId).val()) >= 0 && parseInt($("#" + hourTextId).val()) < 24) {
        if ($("#" + hdntimeSpanId).val() != "") { var arr = $("#" + hdntimeSpanId).val().split(":"); var str = ""; arr[0] = $("#" + hourTextId).val(); $.each(arr, function (i, item) { str += ":" + item }); str = str.substring(1, str.length); $("#" + hdntimeSpanId).val(str) }
        else { var str = $("#" + hourTextId).val() + ":00:00"; $("#" + hdntimeSpanId).val(str) }
    }
    else {
        if ($("#" + hdntimeSpanId).val() != "") { var arr = $("#" + hdntimeSpanId).val().split(":"); var str = ""; arr[0] = "00"; $.each(arr, function (i, item) { str += ":" + item }); str = str.substring(1, str.length); $("#" + hdntimeSpanId).val(str) }
        else { var str = ""; $("#" + hdntimeSpanId).val(str) }
    }
}
function AppendMinutes(hdnTimeSpanId, minuteTextId) {
    if ($.isNumeric($("#" + minuteTextId).val()) && parseInt($("#" + minuteTextId).val()) >= 0 && parseInt($("#" + minuteTextId).val()) < 59) {
        if ($("#" + hdnTimeSpanId).val() != "") { var arr = $("#" + hdnTimeSpanId).val().split(":"); var str = ""; arr[1] = $("#" + minuteTextId).val(); $.each(arr, function (i, item) { str += ":" + item }); str = str.substring(1, str.length); $("#" + hdnTimeSpanId).val(str) }
        else { var str = "00:" + $("#" + minuteTextId).val() + ":00"; $("#" + hdnTimeSpanId).val(str) }
    }
    else {
        if ($("#" + hdnTimeSpanId).val() != "") { var arr = $("#" + hdnTimeSpanId).val().split(":"); var str = ""; arr[1] = "00"; $.each(arr, function (i, item) { str += ":" + item }); str = str.substring(1, str.length); $("#" + hdnTimeSpanId).val(str) }
        else { var str = ""; $("#" + hdnTimeSpanId).val(str) }
    }
}